## Modern Component Patterns

### Data Grid with Virtual Scrolling
```tsx
import React, { useState, useMemo, useCallback, useRef, useEffect } from 'react';
import { useVirtualizer } from '@tanstack/react-virtual';
import { useQuery } from '@tanstack/react-query';
import { ChevronUpIcon, ChevronDownIcon } from '@heroicons/react/24/outline';

interface DataGridProps<T> {
  columns: Column<T>[];
  fetchData: (params: FetchParams) => Promise<{ data: T[]; total: number }>;
  rowHeight?: number;
  pageSize?: number;
}

interface Column<T> {
  key: keyof T;
  header: string;
  width?: number;
  sortable?: boolean;
  render?: (value: any, row: T) => React.ReactNode;
}

interface FetchParams {
  page: number;
  pageSize: number;
  sortBy?: string;
  sortOrder?: 'asc' | 'desc';
  filters?: Record<string, any>;
}

export function DataGrid<T extends Record<string, any>>({
  columns,
  fetchData,
  rowHeight = 40,
  pageSize = 50,
}: DataGridProps<T>) {
  const [page, setPage] = useState(0);
  const [sortConfig, setSortConfig] = useState<{
    key: string;
    order: 'asc' | 'desc';
  } | null>(null);
  const [filters, setFilters] = useState<Record<string, any>>({});

  const parentRef = useRef<HTMLDivElement>(null);

  // Fetch data with React Query
  const { data, isLoading, error } = useQuery({
    queryKey: ['dataGrid', page, sortConfig, filters],
    queryFn: () => fetchData({
      page,
      pageSize,
      sortBy: sortConfig?.key,
      sortOrder: sortConfig?.order,
      filters,
    }),
    keepPreviousData: true,
  });

  // Virtual scrolling
  const rowVirtualizer = useVirtualizer({
    count: data?.data.length ?? 0,
    getScrollElement: () => parentRef.current,
    estimateSize: () => rowHeight,
    overscan: 5,
  });

  // Sort handler
  const handleSort = useCallback((key: string) => {
    setSortConfig(current => {
      if (current?.key === key) {
        return current.order === 'asc'
          ? { key, order: 'desc' }
          : null;
      }
      return { key, order: 'asc' };
    });
  }, []);

  // Filter handler
  const handleFilter = useCallback((key: string, value: any) => {
    setFilters(current => ({
      ...current,
      [key]: value || undefined,
    }));
    setPage(0); // Reset to first page
  }, []);

  const virtualItems = rowVirtualizer.getVirtualItems();

  if (error) {
    return (
      <div className="flex items-center justify-center h-64 text-red-600">
        Error loading data: {error.message}
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <div className="flex bg-gray-50 border-b sticky top-0 z-10">
        {columns.map(column => (
          <div
            key={String(column.key)}
            className="px-4 py-2 font-medium text-left"
            style={{ width: column.width || 'auto', flex: column.width ? 'none' : 1 }}
          >
            <div className="flex items-center gap-2">
              <span>{column.header}</span>
              {column.sortable && (
                <button
                  onClick={() => handleSort(String(column.key))}
                  className="hover:bg-gray-200 rounded p-1"
                >
                  {sortConfig?.key === String(column.key) ? (
                    sortConfig.order === 'asc' ? (
                      <ChevronUpIcon className="w-4 h-4" />
                    ) : (
                      <ChevronDownIcon className="w-4 h-4" />
                    )
                  ) : (
                    <div className="w-4 h-4" />
                  )}
                </button>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* Filter row */}
      <div className="flex bg-gray-100 border-b">
        {columns.map(column => (
          <div
            key={String(column.key)}
            className="px-4 py-2"
            style={{ width: column.width || 'auto', flex: column.width ? 'none' : 1 }}
          >
            <input
              type="text"
              placeholder={`Filter ${column.header}`}
              onChange={(e) => handleFilter(String(column.key), e.target.value)}
              className="w-full px-2 py-1 text-sm border rounded"
            />
          </div>
        ))}
      </div>

      {/* Virtual scroll container */}
      <div
        ref={parentRef}
        className="flex-1 overflow-auto"
        style={{ height: '600px' }}
      >
        {isLoading ? (
          <div className="flex items-center justify-center h-full">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600" />
          </div>
        ) : (
          <div
            style={{
              height: `${rowVirtualizer.getTotalSize()}px`,
              width: '100%',
              position: 'relative',
            }}
          >
            {virtualItems.map(virtualRow => {
              const row = data!.data[virtualRow.index];

              return (
                <div
                  key={virtualRow.key}
                  className="flex border-b hover:bg-gray-50 absolute top-0 left-0 w-full"
                  style={{
                    height: `${virtualRow.size}px`,
                    transform: `translateY(${virtualRow.start}px)`,
                  }}
                >
                  {columns.map(column => (
                    <div
                      key={String(column.key)}
                      className="px-4 py-2 truncate"
                      style={{ width: column.width || 'auto', flex: column.width ? 'none' : 1 }}
                    >
                      {column.render
                        ? column.render(row[column.key], row)
                        : String(row[column.key] ?? '')}
                    </div>
                  ))}
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Pagination */}
      <div className="flex items-center justify-between px-4 py-2 border-t">
        <div className="text-sm text-gray-600">
          Showing {page * pageSize + 1} to {Math.min((page + 1) * pageSize, data?.total ?? 0)} of {data?.total ?? 0}
        </div>
        <div className="flex gap-2">
          <button
            onClick={() => setPage(p => Math.max(0, p - 1))}
            disabled={page === 0}
            className="px-3 py-1 border rounded disabled:opacity-50"
          >
            Previous
          </button>
          <button
            onClick={() => setPage(p => p + 1)}
            disabled={!data || (page + 1) * pageSize >= data.total}
            className="px-3 py-1 border rounded disabled:opacity-50"
          >
            Next
          </button>
        </div>
      </div>
    </div>
  );
}
