## Pinia Store Patterns

### User Authentication Store
```typescript
// stores/auth.ts
import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import { authApi } from '@/api'
import { useRouter } from 'vue-router'
import type { User, LoginCredentials, RegisterData } from '@/types'

export const useAuthStore = defineStore('auth', () => {
  // State
  const user = ref<User | null>(null)
  const token = ref<string | null>(null)
  const loading = ref(false)
  const error = ref<string | null>(null)

  // Router
  const router = useRouter()

  // Getters
  const isAuthenticated = computed(() => !!token.value)
  const userFullName = computed(() => 
    user.value ? `${user.value.firstName} ${user.value.lastName}` : ''
  )
  const userPermissions = computed(() => user.value?.permissions || [])

  // Actions
  async function login(credentials: LoginCredentials) {
    loading.value = true
    error.value = null

    try {
      const response = await authApi.login(credentials)

      token.value = response.data.token
      user.value = response.data.user

      // Store token
      localStorage.setItem('auth_token', token.value)

      // Set axios default header
      authApi.setAuthHeader(token.value)

      // Redirect to dashboard
      await router.push('/dashboard')

      return response.data
    } catch (err: any) {
      error.value = err.response?.data?.message || 'Login failed'
      throw err
    } finally {
      loading.value = false
    }
  }

  async function register(data: RegisterData) {
    loading.value = true
    error.value = null

    try {
      const response = await authApi.register(data)

      // Auto login after registration
      await login({
        email: data.email,
        password: data.password
      })

      return response.data
    } catch (err: any) {
      error.value = err.response?.data?.message || 'Registration failed'
      throw err
    } finally {
      loading.value = false
    }
  }

  async function logout() {
    try {
      await authApi.logout()
    } finally {
      // Clear state
      user.value = null
      token.value = null

      // Clear storage
      localStorage.removeItem('auth_token')

      // Clear auth header
      authApi.clearAuthHeader()

      // Redirect to login
      await router.push('/login')
    }
  }

  async function fetchUser() {
    if (!token.value) return

    try {
      const response = await authApi.getMe()
      user.value = response.data
    } catch (err) {
      // Token invalid, logout
      await logout()
    }
  }

  function hasPermission(permission: string): boolean {
    return userPermissions.value.includes(permission)
  }

  function hasAnyPermission(permissions: string[]): boolean {
    return permissions.some(p => hasPermission(p))
  }

  function hasAllPermissions(permissions: string[]): boolean {
    return permissions.every(p => hasPermission(p))
  }

  // Initialize from localStorage
  function initializeAuth() {
    const storedToken = localStorage.getItem('auth_token')

    if (storedToken) {
      token.value = storedToken
      authApi.setAuthHeader(storedToken)
      fetchUser()
    }
  }

  return {
    // State
    user,
    token,
    loading,
    error,

    // Getters
    isAuthenticated,
    userFullName,
    userPermissions,

    // Actions
    login,
    register,
    logout,
    fetchUser,
    hasPermission,
    hasAnyPermission,
    hasAllPermissions,
    initializeAuth
  }
})
```

### Shopping Cart Store with Persistence
```typescript
// stores/cart.ts
import { defineStore } from 'pinia'
import { ref, computed, watch } from 'vue'
import { useLocalStorage } from '@vueuse/core'
import type { Product, CartItem } from '@/types'

export const useCartStore = defineStore('cart', () => {
  // Persistent state
  const items = useLocalStorage<CartItem[]>('cart_items', [])
  const isOpen = ref(false)

  // Getters
  const itemCount = computed(() => 
    items.value.reduce((total, item) => total + item.quantity, 0)
  )

  const subtotal = computed(() =>
    items.value.reduce((total, item) => 
      total + (item.product.price * item.quantity), 0
    )
  )

  const tax = computed(() => subtotal.value * 0.08) // 8% tax

  const total = computed(() => subtotal.value + tax.value)

  const isEmpty = computed(() => items.value.length === 0)

  // Actions
  function addItem(product: Product, quantity = 1) {
    const existingItem = items.value.find(
      item => item.product.id === product.id
    )

    if (existingItem) {
      existingItem.quantity += quantity
    } else {
      items.value.push({
        id: Date.now().toString(),
        product,
        quantity
      })
    }

    // Show cart
    isOpen.value = true
  }

  function removeItem(itemId: string) {
    const index = items.value.findIndex(item => item.id === itemId)
    if (index > -1) {
      items.value.splice(index, 1)
    }
  }

  function updateQuantity(itemId: string, quantity: number) {
    const item = items.value.find(item => item.id === itemId)
    if (item) {
      if (quantity <= 0) {
        removeItem(itemId)
      } else {
        item.quantity = quantity
      }
    }
  }

  function clearCart() {
    items.value = []
  }

  function toggleCart() {
    isOpen.value = !isOpen.value
  }

  // Optimistic checkout
  async function checkout() {
    const orderItems = [...items.value]

    // Optimistically clear cart
    clearCart()

    try {
      const response = await api.createOrder({
        items: orderItems,
        total: total.value
      })

      return response.data
    } catch (error) {
      // Restore cart on error
      items.value = orderItems
      throw error
    }
  }

  return {
    // State
    items,
    isOpen,

    // Getters
    itemCount,
    subtotal,
    tax,
    total,
    isEmpty,

    // Actions
    addItem,
    removeItem,
    updateQuantity,
    clearCart,
    toggleCart,
    checkout
  }
})
```

### Complex State with Modules Pattern
```typescript
// stores/workspace.ts
import { defineStore, acceptHMRUpdate } from 'pinia'
import { ref, computed, shallowRef } from 'vue'
import type { Project, Task, User, Filter } from '@/types'

export const useWorkspaceStore = defineStore('workspace', () => {
  // Sub-stores pattern
  const projects = ref<Map<string, Project>>(new Map())
  const tasks = ref<Map<string, Task>>(new Map())
  const users = ref<Map<string, User>>(new Map())

  // UI State
  const selectedProjectId = ref<string | null>(null)
  const filters = ref<Filter>({
    status: 'all',
    assignee: null,
    priority: null,
    search: ''
  })

  // Derived state
  const selectedProject = computed(() => 
    selectedProjectId.value 
      ? projects.value.get(selectedProjectId.value) 
      : null
  )

  const projectTasks = computed(() => {
    if (!selectedProjectId.value) return []

    return Array.from(tasks.value.values())
      .filter(task => task.projectId === selectedProjectId.value)
  })

  const filteredTasks = computed(() => {
    let result = projectTasks.value

    // Apply filters
    if (filters.value.status !== 'all') {
      result = result.filter(task => task.status === filters.value.status)
    }

    if (filters.value.assignee) {
      result = result.filter(task => task.assigneeId === filters.value.assignee)
    }

    if (filters.value.priority) {
      result = result.filter(task => task.priority === filters.value.priority)
    }

    if (filters.value.search) {
      const search = filters.value.search.toLowerCase()
      result = result.filter(task => 
        task.title.toLowerCase().includes(search) ||
        task.description?.toLowerCase().includes(search)
      )
    }

    return result
  })

  // Grouped tasks for kanban view
  const tasksByStatus = computed(() => {
    const groups: Record<string, Task[]> = {
      todo: [],
      inProgress: [],
      review: [],
      done: []
    }

    filteredTasks.value.forEach(task => {
      groups[task.status].push(task)
    })

    return groups
  })

  // Actions
  function setProject(projectId: string) {
    selectedProjectId.value = projectId
  }

  function updateTask(taskId: string, updates: Partial<Task>) {
    const task = tasks.value.get(taskId)
    if (task) {
      const updated = { ...task, ...updates, updatedAt: new Date() }
      tasks.value.set(taskId, updated)

      // Emit event for real-time sync
      emitTaskUpdate(updated)
    }
  }

  // Batch operations
  function batchUpdateTasks(taskIds: string[], updates: Partial<Task>) {
    const updatedTasks: Task[] = []

    taskIds.forEach(id => {
      const task = tasks.value.get(id)
      if (task) {
        const updated = { ...task, ...updates, updatedAt: new Date() }
        tasks.value.set(id, updated)
        updatedTasks.push(updated)
      }
    })

    // Emit batch update
    emitBatchTaskUpdate(updatedTasks)
  }

  // Real-time sync
  function syncTask(task: Task) {
    tasks.value.set(task.id, task)
  }

  function syncTasks(newTasks: Task[]) {
    newTasks.forEach(task => {
      tasks.value.set(task.id, task)
    })
  }

  return {
    // State
    projects,
    tasks,
    users,
    selectedProjectId,
    filters,

    // Getters
    selectedProject,
    projectTasks,
    filteredTasks,
    tasksByStatus,

    // Actions
    setProject,
    updateTask,
    batchUpdateTasks,
    syncTask,
    syncTasks
  }
})

// HMR support
if (import.meta.hot) {
  import.meta.hot.accept(acceptHMRUpdate(useWorkspaceStore, import.meta.hot))
}
```

## State Plugins

### Persistence Plugin
```typescript
// plugins/pinia-persistence.ts
import { PiniaPluginContext } from 'pinia'
import { watch } from 'vue'

export function persistencePlugin({ store }: PiniaPluginContext) {
  // Only persist stores with persist option
  if (!store.$state.persist) return

  const storageKey = `pinia-${store.$id}`

  // Restore state
  const stored = localStorage.getItem(storageKey)
  if (stored) {
    try {
      store.$patch(JSON.parse(stored))
    } catch (e) {
      console.error(`Failed to restore state for ${store.$id}`, e)
    }
  }

  // Watch for changes
  watch(
    () => store.$state,
    (state) => {
      try {
        localStorage.setItem(storageKey, JSON.stringify(state))
      } catch (e) {
        console.error(`Failed to persist state for ${store.$id}`, e)
      }
    },
    { deep: true }
  )
}
```

### Undo/Redo Plugin
```typescript
// plugins/pinia-history.ts
import { PiniaPluginContext } from 'pinia'
import { ref } from 'vue'

export function historyPlugin({ store }: PiniaPluginContext) {
  const history = ref<any[]>([])
  const currentIndex = ref(-1)

  // Save initial state
  history.value.push(JSON.parse(JSON.stringify(store.$state)))
  currentIndex.value = 0

  // Add undo/redo methods
  store.undo = () => {
    if (currentIndex.value > 0) {
      currentIndex.value--
      store.$patch(history.value[currentIndex.value])
    }
  }

  store.redo = () => {
    if (currentIndex.value < history.value.length - 1) {
      currentIndex.value++
      store.$patch(history.value[currentIndex.value])
    }
  }

  store.canUndo = () => currentIndex.value > 0
  store.canRedo = () => currentIndex.value < history.value.length - 1

  // Track changes
  store.$subscribe((mutation, state) => {
    // Remove future history
    history.value = history.value.slice(0, currentIndex.value + 1)

    // Add new state
    history.value.push(JSON.parse(JSON.stringify(state)))
    currentIndex.value++

    // Limit history size
    if (history.value.length > 50) {
      history.value.shift()
      currentIndex.value--
    }
  })
}
```

## State Synchronization

### WebSocket Sync
```typescript
// composables/useRealtimeSync.ts
import { onUnmounted } from 'vue'
import { useWorkspaceStore } from '@/stores/workspace'
import { useAuthStore } from '@/stores/auth'
import { io, Socket } from 'socket.io-client'

export function useRealtimeSync() {
  const workspace = useWorkspaceStore()
  const auth = useAuthStore()

  let socket: Socket | null = null

  function connect() {
    socket = io(import.meta.env.VITE_WS_URL, {
      auth: {
        token: auth.token
      }
    })

    socket.on('task:update', (task) => {
      workspace.syncTask(task)
    })

    socket.on('task:batch-update', (tasks) => {
      workspace.syncTasks(tasks)
    })

    socket.on('project:update', (project) => {
      workspace.projects.set(project.id, project)
    })

    socket.on('user:join', (user) => {
      workspace.users.set(user.id, user)
    })

    socket.on('user:leave', (userId) => {
      workspace.users.delete(userId)
    })
  }

  function disconnect() {
    if (socket) {
      socket.disconnect()
      socket = null
    }
  }

  onUnmounted(disconnect)

  return {
    connect,
    disconnect
  }
}
```

