### Feature Slice with RTK
```typescript
// store/slices/cartSlice.ts
import { createSlice, createAsyncThunk, PayloadAction } from '@reduxjs/toolkit';
import { cartApi } from '@/api/cart';
import type { CartItem, Product } from '@/types';

interface CartState {
  items: CartItem[];
  loading: boolean;
  error: string | null;
  lastSync: number | null;
}

const initialState: CartState = {
  items: [],
  loading: false,
  error: null,
  lastSync: null,
};

// Async thunks
export const syncCart = createAsyncThunk(
  'cart/sync',
  async (_, { getState, rejectWithValue }) => {
    try {
      const { auth } = getState() as RootState;
      if (!auth.user) throw new Error('Not authenticated');

      const response = await cartApi.sync();
      return response.data;
    } catch (error) {
      return rejectWithValue(error.message);
    }
  }
);

export const checkout = createAsyncThunk(
  'cart/checkout',
  async (paymentMethod: string, { getState, dispatch }) => {
    const { cart } = getState() as RootState;

    // Optimistic update
    dispatch(clearCart());

    try {
      const response = await cartApi.checkout({
        items: cart.items,
        paymentMethod,
      });
      return response.data;
    } catch (error) {
      // Revert on error
      dispatch(restoreCart(cart.items));
      throw error;
    }
  }
);

const cartSlice = createSlice({
  name: 'cart',
  initialState,
  reducers: {
    addItem: (state, action: PayloadAction<{ product: Product; quantity: number }>) => {
      const { product, quantity } = action.payload;
      const existingItem = state.items.find(item => item.product.id === product.id);

      if (existingItem) {
        existingItem.quantity += quantity;
      } else {
        state.items.push({
          id: Date.now().toString(),
          product,
          quantity,
        });
      }
    },

    updateQuantity: (state, action: PayloadAction<{ id: string; quantity: number }>) => {
      const item = state.items.find(item => item.id === action.payload.id);
      if (item) {
        if (action.payload.quantity <= 0) {
          state.items = state.items.filter(i => i.id !== action.payload.id);
        } else {
          item.quantity = action.payload.quantity;
        }
      }
    },

    removeItem: (state, action: PayloadAction<string>) => {
      state.items = state.items.filter(item => item.id !== action.payload);
    },

    clearCart: (state) => {
      state.items = [];
    },

    restoreCart: (state, action: PayloadAction<CartItem[]>) => {
      state.items = action.payload;
    },
  },

  extraReducers: (builder) => {
    builder
      // Sync cart
      .addCase(syncCart.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(syncCart.fulfilled, (state, action) => {
        state.loading = false;
        state.items = action.payload.items;
        state.lastSync = Date.now();
      })
      .addCase(syncCart.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload as string;
      })

      // Checkout
      .addCase(checkout.fulfilled, (state) => {
        state.items = [];
      });
  },
});

export const { addItem, updateQuantity, removeItem, clearCart, restoreCart } = cartSlice.actions;

// Selectors
export const selectCartItems = (state: RootState) => state.cart.items;
export const selectCartTotal = (state: RootState) =>
  state.cart.items.reduce((total, item) => total + item.product.price * item.quantity, 0);
export const selectCartCount = (state: RootState) =>
  state.cart.items.reduce((count, item) => count + item.quantity, 0);

export default cartSlice.reducer;
```

### RTK Query for API State
```typescript
// store/services/api.ts
import { createApi, fetchBaseQuery } from '@reduxjs/toolkit/query/react';
import type { Product, Order, User } from '@/types';

export const api = createApi({
  reducerPath: 'api',
  baseQuery: fetchBaseQuery({
    baseUrl: '/api',
    prepareHeaders: (headers, { getState }) => {
      const token = (getState() as RootState).auth.token;
      if (token) {
        headers.set('authorization', `Bearer ${token}`);
      }
      return headers;
    },
  }),

  tagTypes: ['Product', 'Order', 'User', 'Cart'],

  endpoints: (builder) => ({
    // Products
    getProducts: builder.query<Product[], { category?: string; search?: string }>({
      query: (params) => ({
        url: 'products',
        params,
      }),
      providesTags: (result) =>
        result
          ? [...result.map(({ id }) => ({ type: 'Product' as const, id })), 'Product']
          : ['Product'],
    }),

    getProduct: builder.query<Product, string>({
      query: (id) => `products/${id}`,
      providesTags: (result, error, id) => [{ type: 'Product', id }],
    }),

    createProduct: builder.mutation<Product, Partial<Product>>({
      query: (product) => ({
        url: 'products',
        method: 'POST',
        body: product,
      }),
      invalidatesTags: ['Product'],
    }),

    updateProduct: builder.mutation<Product, { id: string; data: Partial<Product> }>({
      query: ({ id, data }) => ({
        url: `products/${id}`,
        method: 'PATCH',
        body: data,
      }),
      invalidatesTags: (result, error, { id }) => [{ type: 'Product', id }],
    }),

    // Orders
    getOrders: builder.query<Order[], void>({
      query: () => 'orders',
      providesTags: ['Order'],
    }),

    createOrder: builder.mutation<Order, Partial<Order>>({
      query: (order) => ({
        url: 'orders',
        method: 'POST',
        body: order,
      }),
      invalidatesTags: ['Order', 'Cart'],
    }),

    // User
    getMe: builder.query<User, void>({
      query: () => 'users/me',
      providesTags: ['User'],
    }),

    updateProfile: builder.mutation<User, Partial<User>>({
      query: (data) => ({
        url: 'users/me',
        method: 'PATCH',
        body: data,
      }),
      invalidatesTags: ['User'],
    }),
  }),
});

// Export hooks
export const {
  useGetProductsQuery,
  useGetProductQuery,
  useCreateProductMutation,
  useUpdateProductMutation,
  useGetOrdersQuery,
  useCreateOrderMutation,
  useGetMeQuery,
  useUpdateProfileMutation,
} = api;

// Prefetching
export const { prefetch } = api.endpoints.getProducts;
