## Context API Patterns

### Advanced Context with Reducer
```typescript
// contexts/AppContext.tsx
import React, { createContext, useContext, useReducer, useCallback, useMemo } from 'react';

// Types
interface AppState {
  user: User | null;
  theme: 'light' | 'dark';
  notifications: Notification[];
  settings: Settings;
}

type AppAction =
  | { type: 'SET_USER'; payload: User | null }
  | { type: 'SET_THEME'; payload: 'light' | 'dark' }
  | { type: 'ADD_NOTIFICATION'; payload: Notification }
  | { type: 'REMOVE_NOTIFICATION'; payload: string }
  | { type: 'UPDATE_SETTINGS'; payload: Partial<Settings> };

// Reducer
function appReducer(state: AppState, action: AppAction): AppState {
  switch (action.type) {
    case 'SET_USER':
      return { ...state, user: action.payload };

    case 'SET_THEME':
      return { ...state, theme: action.payload };

    case 'ADD_NOTIFICATION':
      return {
        ...state,
        notifications: [...state.notifications, action.payload],
      };

    case 'REMOVE_NOTIFICATION':
      return {
        ...state,
        notifications: state.notifications.filter(n => n.id !== action.payload),
      };

    case 'UPDATE_SETTINGS':
      return {
        ...state,
        settings: { ...state.settings, ...action.payload },
      };

    default:
      return state;
  }
}

// Context
interface AppContextValue extends AppState {
  // Actions
  setUser: (user: User | null) => void;
  toggleTheme: () => void;
  showNotification: (notification: Omit<Notification, 'id'>) => void;
  hideNotification: (id: string) => void;
  updateSettings: (settings: Partial<Settings>) => void;
}

const AppContext = createContext<AppContextValue | undefined>(undefined);

// Provider
export function AppProvider({ children }: { children: React.ReactNode }) {
  const [state, dispatch] = useReducer(appReducer, {
    user: null,
    theme: 'light',
    notifications: [],
    settings: {
      language: 'en',
      currency: 'USD',
      notifications: true,
    },
  });

  // Actions
  const setUser = useCallback((user: User | null) => {
    dispatch({ type: 'SET_USER', payload: user });
  }, []);

  const toggleTheme = useCallback(() => {
    dispatch({
      type: 'SET_THEME',
      payload: state.theme === 'light' ? 'dark' : 'light',
    });
  }, [state.theme]);

  const showNotification = useCallback((notification: Omit<Notification, 'id'>) => {
    const id = Date.now().toString();
    dispatch({
      type: 'ADD_NOTIFICATION',
      payload: { ...notification, id },
    });

    // Auto-hide after 5 seconds
    setTimeout(() => {
      dispatch({ type: 'REMOVE_NOTIFICATION', payload: id });
    }, 5000);
  }, []);

  const hideNotification = useCallback((id: string) => {
    dispatch({ type: 'REMOVE_NOTIFICATION', payload: id });
  }, []);

  const updateSettings = useCallback((settings: Partial<Settings>) => {
    dispatch({ type: 'UPDATE_SETTINGS', payload: settings });
  }, []);

  // Memoized value
  const value = useMemo(
    () => ({
      ...state,
      setUser,
      toggleTheme,
      showNotification,
      hideNotification,
      updateSettings,
    }),
    [state, setUser, toggleTheme, showNotification, hideNotification, updateSettings]
  );

  return <AppContext.Provider value={value}>{children}</AppContext.Provider>;
}

// Hook
export function useApp() {
  const context = useContext(AppContext);
  if (!context) {
    throw new Error('useApp must be used within AppProvider');
  }
  return context;
}

// Selector hooks for performance
export function useUser() {
  const { user } = useApp();
  return user;
}

export function useTheme() {
  const { theme, toggleTheme } = useApp();
  return { theme, toggleTheme };
}
```

## State Machine with XState

```typescript
// machines/checkoutMachine.ts
import { createMachine, assign } from 'xstate';

interface CheckoutContext {
  items: CartItem[];
  shippingAddress: Address | null;
  paymentMethod: PaymentMethod | null;
  error: string | null;
}

type CheckoutEvent =
  | { type: 'SET_SHIPPING'; address: Address }
  | { type: 'SET_PAYMENT'; method: PaymentMethod }
  | { type: 'SUBMIT' }
  | { type: 'RETRY' }
  | { type: 'CANCEL' };

export const checkoutMachine = createMachine<CheckoutContext, CheckoutEvent>({
  id: 'checkout',
  initial: 'cart',
  context: {
    items: [],
    shippingAddress: null,
    paymentMethod: null,
    error: null,
  },

  states: {
    cart: {
      on: {
        SET_SHIPPING: {
          target: 'shipping',
          actions: assign({
            shippingAddress: (_, event) => event.address,
          }),
        },
      },
    },

    shipping: {
      on: {
        SET_PAYMENT: {
          target: 'payment',
          actions: assign({
            paymentMethod: (_, event) => event.method,
          }),
        },
        CANCEL: 'cart',
      },
    },

    payment: {
      on: {
        SUBMIT: 'processing',
        CANCEL: 'shipping',
      },
    },

    processing: {
      invoke: {
        src: 'processPayment',
        onDone: {
          target: 'success',
        },
        onError: {
          target: 'error',
          actions: assign({
            error: (_, event) => event.data.message,
          }),
        },
      },
    },

    error: {
      on: {
        RETRY: 'processing',
        CANCEL: 'payment',
      },
    },

    success: {
      type: 'final',
    },
  },
});

// React integration
import { useMachine } from '@xstate/react';

export function useCheckout() {
  const [state, send] = useMachine(checkoutMachine, {
    services: {
      processPayment: async (context) => {
        const response = await api.processCheckout({
          items: context.items,
          shipping: context.shippingAddress,
          payment: context.paymentMethod,
        });
        return response.data;
      },
    },
  });

  return {
    state,
    setShipping: (address: Address) => send({ type: 'SET_SHIPPING', address }),
    setPayment: (method: PaymentMethod) => send({ type: 'SET_PAYMENT', method }),
    submit: () => send('SUBMIT'),
    retry: () => send('RETRY'),
    cancel: () => send('CANCEL'),
  };
}
